const{chromium}=require('playwright'),fs=require('fs'),assert=require('node:assert/strict');
(async()=>{const output='qa-artifacts/tablet-containment';fs.mkdirSync(output,{recursive:true});const browser=await chromium.launch({headless:true}),results=[],base=new Map();
for(const [w,h]of [[320,700],[360,800],[375,812],[390,844],[430,932],[650,900],[651,900],[768,1024],[900,1024],[901,1024],[1024,768],[1363,936],[1440,936]])for(const lang of ['en','ar'])for(const variant of ['before','after']){
const id=lang+'-'+w+'-'+variant,r={id,w,h,lang,variant,errors:[]},c=await browser.newContext({viewport:{width:w,height:h},serviceWorkers:'block'});results.push(r);
await c.route('**/*',route=>{const q=route.request(),u=new URL(q.url());if(!['GET','HEAD'].includes(q.method())||/google-analytics|googletagmanager|doubleclick|cloudflareinsights|wa.me|whatsapp.com|embed.tawk.to/.test(u.hostname))return route.abort();return route.continue()});
await c.addInitScript(()=>{window.__qaShift=[];new PerformanceObserver(l=>l.getEntries().forEach(e=>{if(!e.hadRecentInput)window.__qaShift.push(e.value)})).observe({type:'layout-shift',buffered:true})});const p=await c.newPage();
try{await p.goto((variant==='before'?'https://elajmeindia.com':process.env.HEADER_PREVIEW)+(lang==='ar'?'/ar/':'/'),{waitUntil:'networkidle'});await p.evaluate(()=>document.fonts.ready);
r.geometry=await p.evaluate(()=>{const box=e=>{const r=e.getBoundingClientRect();return{x:r.x,y:r.y,w:r.width,h:r.height}},copy=document.querySelector('#home .hero-copy'),marker=copy.querySelector('.eyebrow-dot');return{hero:box(copy),marker:box(marker),heading:box(copy.querySelector('h1')),font:getComputedStyle(copy.querySelector('h1')).font,header:box(document.querySelector('.master-site-header')),form:box(document.querySelector('#patientEnquiryForm')),footer:getComputedStyle(document.querySelector('.elajme-v2-main')).gridTemplateColumns,cls:window.__qaShift.reduce((x,v)=>x+v,0),overflow:document.documentElement.scrollWidth>innerWidth,cards:[...document.querySelectorAll('.treatments-section .treatment-card')].map(box)}});
const key=lang+'-'+w;if(variant==='before')base.set(key,r.geometry);else{const old=base.get(key),same=lang==='ar'||w<=430||w>=901;assert.equal(r.geometry.font,old.font,'Approved hero typography');if(same){const compactHeader=w<=900?112:110;assert.equal(r.geometry.header.h,compactHeader,'Approved compact header height at '+key);for(const k of ['hero','heading']){const before=old[k],after=r.geometry[k],expectedShift=compactHeader-old.header.h;assert.deepEqual(after,{...before,y:before.y+expectedShift},'Only expected header-height shift in '+k+' at '+key)}const form=r.geometry.form,previousForm=old.form;assert(form.h<=previousForm.h+1,'Approved enquiry form must not grow at '+key);assert(form.w<=previousForm.w+1,'Approved enquiry form must not widen at '+key);assert(form.x>=-1&&form.x+form.w<=w+1,'Enquiry form within viewport at '+key)}if(lang==='en'&&w>=561&&w<=900)assert(r.geometry.marker.x>=24,'Tablet hero gutter');if(lang==='en')assert(r.geometry.cards.every(b=>b.x>=0&&b.x+b.w<=w+1),'Treatment cards within viewport');assert(!r.geometry.overflow,'No horizontal overflow');assert(r.geometry.cls<.1,'Startup CLS below 0.1');}
if([390,650,651,768,900,901,1440].includes(w)){await p.screenshot({path:output+'/'+id+'-hero.png'});await p.locator('.treatments-section').scrollIntoViewIfNeeded();await p.screenshot({path:output+'/'+id+'-treatments.png'});await p.locator('#patientEnquiryForm').screenshot({path:output+'/'+id+'-form.png'});}
// Record the 901px axe observation at two ordinary scroll positions before considering any fix.
if(w===901){await p.addScriptTag({path:require.resolve('axe-core')});r.axe=[];for(const y of [0,1000]){await p.evaluate(y=>{document.documentElement.style.scrollBehavior='auto';scrollTo(0,y)},y);r.axe.push({y,violations:await p.evaluate(async()=>{const a=await axe.run(document,{runOnly:{type:'tag',values:['wcag2a','wcag2aa','wcag21aa','wcag22aa']}});return a.violations.map(v=>({id:v.id,nodes:v.nodes.map(n=>n.target)}))})})}}
if(lang==='ar'&&w===390){await p.locator('#patientMobile').fill('+96890000000');r.phone=await p.locator('#patientMobile').evaluate(e=>({direction:getComputedStyle(e).direction,value:e.value}));await p.locator('#patientEnquiryForm').screenshot({path:output+'/'+id+'-phone-direction.png'});}
}catch(e){r.errors.push(e.message);await p.screenshot({path:output+'/'+id+'-failure.png'}).catch(()=>{})}await c.close();fs.writeFileSync(output+'/results.json',JSON.stringify(results,null,2));console.log(JSON.stringify({id,errors:r.errors,geometry:r.geometry}));}
await browser.close();assert(!results.some(r=>r.errors.length),'Tablet containment regression failed');})();
